//! Chars a host terminal may draw wider or narrower than ratatui counts them (MAX-271)
//!
//! Generated by `tools/widths` (Unicode 15.1.0 and 18.0.0 data, unicode-width 0.2.3), don't edit:
//! 65823 code points in 138 ranges

/// Whether a host may give `c` another width than ratatui
pub fn is_unsure(c: char) -> bool {
    let cp = u32::from(c);
    // below the first range (ASCII, Latin-1 but the soft hyphen): no search
    if cp < RANGES[0].0 {
        return false;
    }
    RANGES
        .binary_search_by(|&(start, end)| {
            if end < cp {
                std::cmp::Ordering::Less
            } else if start > cp {
                std::cmp::Ordering::Greater
            } else {
                std::cmp::Ordering::Equal
            }
        })
        .is_ok()
}

